package com.lims.controller;
import com.lims.model.User;import com.lims.service.ExportService;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;
@WebServlet(name="SalesServlet",urlPatterns={"/app/sales/export-requests","/app/sales/export-request-form"})
public class SalesServlet extends BaseServlet{
 private final ExportService service=new ExportService();
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=getCurrentUser(req);if(u==null||!service.sales(u.getUserId())){resp.sendError(403,"Sales Staff role required");return;}req.setAttribute("user",u);req.setAttribute("notice",req.getParameter("notice"));req.setAttribute("error",req.getParameter("error"));if(req.getServletPath().endsWith("/export-request-form")){req.setAttribute("customers",service.customers());req.setAttribute("products",service.products());forward(req,resp,"sales-export-request-form.jsp");}else{req.setAttribute("requests",service.salesRequests(u.getUserId()));forward(req,resp,"sales-export-requests.jsp");}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{req.setCharacterEncoding("UTF-8");User u=getCurrentUser(req);if(u==null||!service.sales(u.getUserId())){resp.sendError(403,"Sales Staff role required");return;}try{int id=service.createRequest(u,req.getParameter("customerId"),req.getParameterValues("productIds"),req.getParameterValues("quantities"),getClientIP(req),req.getHeader("User-Agent"));go(req,resp,"notice","Đã gửi yêu cầu xuất kho #"+id+" cho Manager duyệt.");}catch(IllegalArgumentException|IllegalStateException e){go(req,resp,"error",e.getMessage());}}
 private void go(HttpServletRequest req,HttpServletResponse resp,String k,String v)throws IOException{redirect(req,resp,"/app/sales/export-requests?"+k+"="+URLEncoder.encode(v,StandardCharsets.UTF_8));}
}
